using System;using System.Collections.Generic;using System.IO;using System.Management;using System.Threading.Tasks;
internal static class DeviceHealth {
 static readonly object gate=new object();static DateTime updated=DateTime.MinValue;static object cached;static Task<object> pending;
 internal static Task<object> Snapshot(){lock(gate){if(cached!=null&&(DateTime.UtcNow-updated).TotalSeconds<5)return Task.FromResult(cached);if(pending!=null&&!pending.IsCompleted)return pending;pending=Task.Run<object>(()=>{var value=Read();lock(gate){cached=value;updated=DateTime.UtcNow;}return value;});return pending;}}
 static double Number(object value){try{return Convert.ToDouble(value);}catch{return 0;}}
 static List<Dictionary<string,object>> Query(string scope,string query){var rows=new List<Dictionary<string,object>>();using(var search=new ManagementObjectSearcher(scope,query)){search.Options.Timeout=TimeSpan.FromSeconds(4);using(var values=search.Get())foreach(ManagementObject item in values){using(item){var row=new Dictionary<string,object>();foreach(PropertyData p in item.Properties)row[p.Name]=p.Value;rows.Add(row);if(rows.Count>=8)break;}}}return rows;}
 static object Read(){
  object cpu=null,memory=null,battery=null;string os=null;double? uptime=null;var gpu=new List<string>();var disks=new List<object>();var errors=new List<string>();
  try{var rows=Query("root\\cimv2","SELECT Name,LoadPercentage,NumberOfCores,NumberOfLogicalProcessors FROM Win32_Processor");if(rows.Count>0){var p=rows[0];cpu=new{name=p["Name"],load=p["LoadPercentage"]==null?(double?)null:Number(p["LoadPercentage"]),cores=Number(p["NumberOfCores"]),threads=Number(p["NumberOfLogicalProcessors"])};}}catch{errors.Add("Processor information unavailable");}
  try{foreach(var p in Query("root\\cimv2","SELECT Name FROM Win32_VideoController"))if(p["Name"]!=null)gpu.Add(p["Name"].ToString());}catch{errors.Add("Graphics information unavailable");}
  try{var rows=Query("root\\cimv2","SELECT Caption,TotalVisibleMemorySize,FreePhysicalMemory,LastBootUpTime FROM Win32_OperatingSystem");if(rows.Count>0){var p=rows[0];os=Convert.ToString(p["Caption"]);memory=new{total=Number(p["TotalVisibleMemorySize"])*1024,available=Number(p["FreePhysicalMemory"])*1024};uptime=Math.Max(0,(DateTime.Now-ManagementDateTimeConverter.ToDateTime(Convert.ToString(p["LastBootUpTime"]))).TotalSeconds);}}catch{errors.Add("Memory and OS information unavailable");}
  try{var p=System.Windows.Forms.SystemInformation.PowerStatus;var percent=p.BatteryLifePercent;if(percent>=0&&percent<=1&&(p.BatteryChargeStatus&System.Windows.Forms.BatteryChargeStatus.NoSystemBattery)==0)battery=new{percent=Math.Round(percent*100),charging=p.PowerLineStatus==System.Windows.Forms.PowerLineStatus.Online};}catch{errors.Add("Battery information unavailable");}
  foreach(string name in Environment.GetLogicalDrives()){if(name.StartsWith("E:",StringComparison.OrdinalIgnoreCase))continue;try{var d=new DriveInfo(name);if(d.DriveType==DriveType.Fixed&&d.IsReady)disks.Add(new{name=d.Name.TrimEnd('\\'),total=(double)d.TotalSize,free=(double)d.AvailableFreeSpace});}catch{}}
  return new{cpu,gpu,gpuUsage=GpuUsage(),memory,battery,disks,os,uptimeSeconds=uptime,errors,at=DateTime.UtcNow.ToString("o")};
 }
 internal static double? GpuUsage(){try{var engines=new Dictionary<string,double>();using(var search=new ManagementObjectSearcher("root\\cimv2","SELECT Name,UtilizationPercentage FROM Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine")){search.Options.Timeout=TimeSpan.FromSeconds(3);using(var rows=search.Get()){int count=0;foreach(ManagementObject item in rows){using(item){if(++count>8192)return null;string name=Convert.ToString(item["Name"]);int index=name.IndexOf("_luid_",StringComparison.Ordinal);if(index<0)continue;string key=name.Substring(index);double previous;engines.TryGetValue(key,out previous);engines[key]=previous+Number(item["UtilizationPercentage"]);}}}}double max=0;foreach(double value in engines.Values)max=Math.Max(max,value);return engines.Count==0?(double?)null:Math.Min(100,Math.Round(max));}catch{return null;}}
 internal static object Defender(){try{var rows=Query("root\\Microsoft\\Windows\\Defender","SELECT AntivirusEnabled,RealTimeProtectionEnabled,AntivirusSignatureLastUpdated FROM MSFT_MpComputerStatus");if(rows.Count>0){var p=rows[0];return new{available=true,antivirus=Convert.ToBoolean(p["AntivirusEnabled"]),realtime=Convert.ToBoolean(p["RealTimeProtectionEnabled"]),updated=Convert.ToString(p["AntivirusSignatureLastUpdated"])};}}catch{}return new{available=false};}
 internal static List<Dictionary<string,object>> Detections(){try{var result=new List<Dictionary<string,object>>();using(var search=new ManagementObjectSearcher("root\\Microsoft\\Windows\\Defender","SELECT DetectionID,InitialDetectionTime,LastThreatStatusChangeTime,ThreatID,ActionSuccess,CleaningActionID,Resources FROM MSFT_MpThreatDetection")){search.Options.Timeout=TimeSpan.FromSeconds(4);using(var rows=search.Get())foreach(ManagementObject item in rows){using(item){if(result.Count>=4096)return null;var row=new Dictionary<string,object>();foreach(PropertyData p in item.Properties)row[p.Name]=p.Value;result.Add(row);}}}result.Sort((a,b)=>string.CompareOrdinal(Convert.ToString(b["LastThreatStatusChangeTime"]),Convert.ToString(a["LastThreatStatusChangeTime"])));return result.GetRange(0,Math.Min(64,result.Count));}catch{return null;}}
}
